// Exercise the primary template constructor with B == true
// This type exists regardless of nested typedef presence; ctor is trivial.
YAML::enable_if_c<true, int> x_true;
(void)x_true;  // silence unused warning
// Validation: construction of the enable_if_c primary template with B=true succeeds and does nothing.

// Exercise the explicit specialization with B == false
YAML::enable_if_c<false, int> x_false;
(void)x_false;  // trivial, no nested typedef expected
// Validation: specialization is constructible and performs no work.

// Exercise the primary template with B == false (the case where nested typedef exists)
YAML::disable_if_c<false, int> x_disable_ok;
(void)x_disable_ok;
// Also instantiate with B == true to ensure constructor exists even when typedef does not
YAML::disable_if_c<true, int> x_disable_no_type;
(void)x_disable_no_type;
// Validation: both instantiations construct trivially without runtime effects.

// Exercise the explicit specialization with B == true
YAML::disable_if_c<true, int> x_disable_true;
(void)x_disable_true;
// Validation: specialization is constructible and performs no work.

// Instantiate the Streamable == true branch using a type that is streamable (int)
int key = *FUZZ_PARAM(int);
// Call the implementation that streams the key into a std::stringstream
std::string out = streamable_to_string<int, true>::impl(key);
// Light sanity: ensure result length is bounded in practice (implementation-dependent but small for ints)
if (out.size() > 64) { FUZZ_BAIL(); }
// Validation: Successfully exercised the streaming path; returned string is consumed and bounded.

// Instantiate the Streamable == false specialization with a non-streamable key type
struct NotStreamable { int v; };
NotStreamable k{ *FUZZ_PARAM(int) };
std::string out = streamable_to_string<NotStreamable, false>::impl(k);
// The false specialization must return an empty string regardless of input
