import random
import struct
from typing import List

# This generator produces valid/interesting YAML documents as bytes, intended to be
# written to a temporary file that FUZZ_PARAM_FILENAME() refers to. The fuzz stubs
# call YAML::LoadFile and YAML::LoadAllFromFile, so we focus on producing syntactically
# valid YAML covering multiple constructs and multi-document streams.

# Constraints:
# - Return <= 4096 bytes
# - Seeded randomness
# - Prefer valid YAML; include multiple docs sometimes

SCALARS = [
    "",  # empty scalar
    "null",
    "~",
    "NULL",
    "true",
    "false",
    "yes",
    "no",
    "0",
    "-1",
    "1_000",
    "3.14159",
    ".nan",
    ".inf",
    "-.inf",
    "2025-01-01",
    "12:34:56",
    "key: value",  # will be quoted when needed
    "# not a comment",
    "multi word text"
]

TAGS = ["!custom", "!!str", "!!int", "!!float", "tag:yaml.org,2002:str"]
ANCHOR_NAMES = ["a", "b1", "ANCH", "x_y", "root"]


def rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))


def choose(r: random.Random, arr: List[str]):
    return arr[r.randrange(len(arr))]


def yaml_quote_if_needed(s: str) -> str:
    # Quote when string contains YAML special chars likely to confuse plain scalars
    if s == "" or any(ch in s for ch in [":", "#", "\n", "\t"]) or s.strip() != s or s in {"null", "~", "true", "false", "yes", "no"}:
        return '"' + s.replace('"', '\\"') + '"'
    return s


def gen_scalar(r: random.Random) -> str:
    s = choose(r, SCALARS)
    # Occasionally force single or double quotes or literal/block style
    style = r.randrange(6)
    if style == 0:
        return yaml_quote_if_needed(s)
    elif style == 1:
        return "'" + s.replace("'", "''") + "'"
    elif style == 2:
        # double quoted with escapes
        return '"' + s.replace('"', '\\"').replace("\n", "\\n") + '"'
    elif style == 3:
        # literal block scalar
        lines = s if s else "l1\nl2\n  indented\n# not comment\n"
        return "|\n  " + "\n  ".join(lines.splitlines() or [""])
    elif style == 4:
        # folded block scalar
        lines = s if s else "fold this\nline two\nline three"
        return ">\n  " + "\n  ".join(lines.splitlines())
    else:
        return yaml_quote_if_needed(s)


def gen_sequence(r: random.Random, depth: int) -> str:
    n = r.randrange(0, 6) if depth > 0 else r.randrange(1, 6)
    # choose between block and flow style
    if rand_bool(r):
        # block style
        items = []
        for _ in range(n):
            items.append("- " + gen_node(r, depth + 1).replace("\n", "\n  "))
        return "\n".join(items) if items else "[]"
    else:
        # flow style
        items = [gen_scalar(r) if rand_bool(r) else gen_simple_value(r, depth + 1) for _ in range(n)]
        return "[ " + ", ".join(items) + " ]"


def gen_mapping(r: random.Random, depth: int) -> str:
    n = r.randrange(0, 6) if depth > 0 else r.randrange(1, 6)
    entries = []
    used_keys = set()
    for i in range(n):
        key = yaml_quote_if_needed(choose(r, SCALARS) or f"k{i}")
        if key in used_keys:
            key = key + str(i)
        used_keys.add(key)
        value = gen_node(r, depth + 1)
        # Occasionally use explicit tag or anchor/alias pairs
        prefix = ""
        if rand_bool(r) and depth < 2:
            if rand_bool(r):
                prefix += f"&{choose(r, ANCHOR_NAMES)} "
            if rand_bool(r):
                prefix += f"{choose(r, TAGS)} "
        line = f"{key}: {prefix}{value}"
        # Sometimes put value on next indented line (block style)
        if "\n" in value and not value.lstrip().startswith("["):
            ind = "\n  ".join(value.splitlines())
            line = f"{key}:\n  {ind}"
        entries.append(line)
    if not entries:
        return "{}"
    return "\n".join(entries)


def gen_alias_section(r: random.Random) -> str:
    # Define an anchored node and later reference it
    name = choose(r, ANCHOR_NAMES)
    val = gen_scalar(r)
    doc = f"anchor: &{name} {val}\nuse1: *{name}\nlist:\n  - *{name}\n  - {gen_scalar(r)}"
    return doc


def gen_simple_value(r: random.Random, depth: int) -> str:
    t = r.randrange(3)
    if t == 0:
        return gen_scalar(r)
    elif t == 1:
        return gen_sequence(r, depth)
    else:
        return gen_mapping(r, depth)


def gen_node(r: random.Random, depth: int) -> str:
    if depth > 3:
        return gen_scalar(r)
    choice = r.randrange(4)
    if choice == 0:
        return gen_scalar(r)
    elif choice == 1:
        return gen_sequence(r, depth)
    elif choice == 2:
        return gen_mapping(r, depth)
    else:
        # null sentinel sometimes
        return choose(r, ["null", "~", "" or "~"]) or "~"


def gen_document(r: random.Random) -> str:
    # Optionally include directives and explicit doc markers
    parts = []
    if rand_bool(r):
        parts.append("%YAML 1.2")
    if rand_bool(r):
        parts.append("%TAG !e! tag:example.com,2025:")
    if rand_bool(r):
        parts.append("---")
    # Top-level can be mapping, sequence, or scalar
    top_choice = r.randrange(5)
    if top_choice == 0:
        content = gen_mapping(r, 0)
    elif top_choice == 1:
        content = gen_sequence(r, 0)
    elif top_choice == 2:
        content = gen_alias_section(r)
    elif top_choice == 3:
        # Flow map
        kv = [f"{yaml_quote_if_needed('k'+str(i))}: {gen_scalar(r)}" for i in range(r.randrange(1, 5))]
        content = "{ " + ", ".join(kv) + " }"
    else:
        content = gen_scalar(r)
    parts.append(content)
    if rand_bool(r):
        parts.append("...")
    return "\n".join([p for p in parts if p != ""]).strip() + "\n"


def gen_multi_document(r: random.Random) -> str:
    doc_count = r.randrange(2, 6)
    docs = []
    for i in range(doc_count):
        docs.append(gen_document(r))
    # Ensure proper separators between docs for LoadAllFromFile
    return ("---\n" + "---\n".join(docs)).rstrip() + "\n"


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide between single or multi-document
    if r.random() < 0.5:
        text = gen_document(r)
    else:
        text = gen_multi_document(r)
    # Add some trailing comments and whitespace sometimes
    if r.random() < 0.5:
        comment_lines = []
        for _ in range(r.randrange(1, 4)):
            comment_lines.append("# " + choose(r, ["trailing", "meta", "info", "测试", "коммент"]))
        text += "\n".join(comment_lines) + "\n"
    # Size cap
    b = text.encode('utf-8')
    if len(b) > 4096:
        b = b[:4096]
        # ensure final byte ends with newline if possible
        if not b.endswith(b"\n"):
            b = b[:-1] + b"\n"
    return b
